import java.util.HashMap;
public class Main {
    public static void main(String[] args) {
        HashMap<String,Integer> counts = new HashMap<>();
        counts.put("read", 2);
        counts.put("read", 5);
        System.out.println(counts.getOrDefault("read", 0));
        System.out.println(counts.size());
    }
}

